target.css:
:root {
  --ink: #243330;
  --muted: #63736e;
  --paper: #fffdf7;
  --mist: #edf1e9;
  --line: #cbd5ca;
  --sky: #7e9ccb;
  --rose: #f0b487;
  --moss: #385b4d;
  --deep-moss: #203c34;
  --cream: #fff4d8;
}

.continuity-board {
  box-sizing: border-box;
  width: 500px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--ink);
  border-radius: 18px;
}

.board-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px 14px;
  border-bottom: 1px solid var(--line);
}

.reel-mark {
  display: grid;
  width: 31px;
  height: 31px;
  flex: 0 0 auto;
  place-items: center;
  color: var(--cream);
  background: var(--deep-moss);
  border-radius: 9px;
  font-size: 18px;
  line-height: 1;
}

.title-block {
  min-width: 0;
  flex: 1;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.7px;
  line-height: 1.1;
}

h1 {
  margin: 0;
  font-size: 18px;
  font-weight: 750;
  letter-spacing: -0.25px;
  line-height: 1.1;
}

.status {
  padding: 5px 7px;
  color: var(--deep-moss);
  background: var(--cream);
  border: 1px solid var(--moss);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.55px;
}

.workspace {
  display: grid;
  grid-template-columns: 1.14fr 0.86fr;
  gap: 12px;
  padding: 12px 14px;
  background: var(--mist);
}

.shot-preview {
  margin: 0;
  overflow: hidden;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 12px;
}

.scene {
  position: relative;
  height: 91px;
  overflow: hidden;
  background: var(--sky);
}

.sun {
  position: absolute;
  top: 18px;
  right: 30px;
  width: 27px;
  height: 27px;
  background: var(--rose);
  border: 3px solid var(--cream);
  border-radius: 50%;
}

.ridge {
  position: absolute;
  bottom: -20px;
  width: 150px;
  height: 74px;
  transform: rotate(45deg);
  border-radius: 10px;
}

.ridge.back {
  left: 18px;
  background: var(--moss);
}

.ridge.front {
  right: -24px;
  background: var(--deep-moss);
}

figcaption {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 10px;
}

.shot-code {
  color: var(--deep-moss);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.45px;
}

.film-note {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.2;
}

.palette-panel {
  padding: 10px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 12px;
}

.panel-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding-bottom: 7px;
  border-bottom: 1px solid var(--line);
}

h2 {
  margin: 0;
  font-size: 13px;
  font-weight: 800;
  line-height: 1.2;
}

.panel-head span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.palette-list {
  display: grid;
  gap: 5px;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}

.palette-list li {
  display: grid;
  grid-template-columns: 14px 1fr auto;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.swatch {
  width: 12px;
  height: 12px;
  border: 1px solid var(--ink);
  border-radius: 3px;
}

.swatch.sky {
  background: var(--sky);
}

.swatch.rose {
  background: var(--rose);
}

.swatch.moss {
  background: var(--moss);
}

.tone-name {
  font-size: 11px;
  font-weight: 650;
  line-height: 1.2;
}

.tone-code {
  color: var(--muted);
  font-size: 9px;
  line-height: 1;
}

.board-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 14px;
  border-top: 1px solid var(--line);
}

.footer-copy {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
  line-height: 1.2;
}

button {
  padding: 7px 10px;
  color: var(--cream);
  background: var(--deep-moss);
  border: 1px solid var(--deep-moss);
  border-radius: 8px;
  font-size: 11px;
  font-weight: 750;
  line-height: 1;
}

